<?php
session_start();
require_once __DIR__.'/config/db.php';
require_once __DIR__ . '/config/helpers.php';
require_once __DIR__.'/config/report_schema.php';
if(!isset($_SESSION['user'])||($_SESSION['user']['role']??'')!=='Teacher'){header('Location: login.php');exit;}
$schemaError='';try{sems_ensure_event_reports($pdo);}catch(Throwable $schemaFailure){$schemaError='Could not prepare the report database. Please import database/upgrade_reports.sql in phpMyAdmin.';}
$user=$_SESSION['user'];$uid=(int)$user['userID'];
if(empty($_SESSION['sems_csrf']))$_SESSION['sems_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['sems_csrf'];$message='';$error='';
if($schemaError!=='')$error=$schemaError;
if($_SERVER['REQUEST_METHOD']==='POST'&&$schemaError===''){
 if(!hash_equals($csrf,$_POST['csrf']??''))$error='Your session expired. Refresh and try again.';
 else{
  try{$title=trim((string)($_POST['title']??''));$eventID=(int)($_POST['eventID']??0);$start='';$end='';$objectives=trim((string)($_POST['objectives']??''));$outcomes=trim((string)($_POST['outcomes']??''));$issues=trim((string)($_POST['issues']??''));$recommendations=trim((string)($_POST['recommendations']??''));
   if($title===''||strlen($title)>180||$objectives===''||$outcomes===''||max(strlen($objectives),strlen($outcomes),strlen($issues),strlen($recommendations))>10000)throw new RuntimeException('Complete the title, event, objectives and outcomes. Each report section has a 10,000 character limit.');
   $check=$pdo->prepare('SELECT e.eventID,e.eventName,e.eventDate FROM events e WHERE e.eventID=? AND (e.createdBy=? OR EXISTS(SELECT 1 FROM event_tasks t WHERE t.eventID=e.eventID AND t.assignedTo=?))');$check->execute([$eventID,$uid,$uid]);$event=$check->fetch();if(!$event)throw new RuntimeException('Select an event that you handle or have a committee task for.');$start=$end=$event['eventDate'];$start=$end=$event['eventDate'];$start=$end=$event['eventDate'];
   $principalID=(int)$pdo->query("SELECT userID FROM users WHERE role='Principal' AND status='Active' ORDER BY userID DESC LIMIT 1")->fetchColumn();if(!$principalID)throw new RuntimeException('There is no active Principal account to receive this report.');
   $metric=$pdo->prepare("SELECT (SELECT COUNT(*) FROM registrations r WHERE r.eventID=? AND r.status='Approved') approved,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=? AND r.status='Pending Verification') pending,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=? AND r.status='Rejected') rejected,(SELECT COUNT(*) FROM attendance a JOIN registrations r ON r.eventID=a.eventID AND r.studentID=a.studentID WHERE a.eventID=? AND r.status='Approved' AND a.status='Present') present,(SELECT COUNT(*) FROM attendance a JOIN registrations r ON r.eventID=a.eventID AND r.studentID=a.studentID WHERE a.eventID=? AND r.status='Approved' AND a.status='Absent') absent,(SELECT COUNT(*) FROM financial_assistance fa JOIN students s ON s.userID=fa.userID JOIN registrations r ON r.studentID=s.studentID WHERE r.eventID=? AND fa.status='Approved') assistance,(SELECT COUNT(*) FROM payments p WHERE p.eventID=? AND p.status='Verified') paymentCount,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.eventID=? AND p.status='Verified') paymentAmount,(SELECT COUNT(*) FROM feedback f WHERE f.eventID=?) feedbackCount");$metric->execute(array_fill(0,9,$eventID));$m=$metric->fetch();
   $auto='Registrations: '.$m['approved'].' approved, '.$m['pending'].' pending verification, '.$m['rejected'].' rejected. Attendance: '.$m['present'].' present, '.$m['absent'].' absent. Approved financial assistance applications: '.$m['assistance'].'. Verified payments: '.$m['paymentCount'].' record(s), RM '.number_format((float)$m['paymentAmount'],2).'. Student feedback: '.$m['feedbackCount'].' submission(s).';
   $updateID=(int)($_POST['updateReportID']??0);$reportPhotoDescription=trim((string)($_POST['reportPhotoDescription']??''));if(strlen($reportPhotoDescription)>1000)throw new RuntimeException('Photo description is limited to 1,000 characters.');
   $reportPhotoPath=null;if($updateID){$old=$pdo->prepare("SELECT reportID,reportPhoto FROM event_reports WHERE reportID=? AND submittedBy=? AND status IN ('Resubmit','Needs Revision')");$old->execute([$updateID,$uid]);$oldReport=$old->fetch();if(!$oldReport)throw new RuntimeException('This report is not awaiting resubmission.');$reportPhotoPath=$oldReport['reportPhoto']??null;}
   $photoUpload=$_FILES['reportPhoto']??null;if($photoUpload&&$photoUpload['error']!==UPLOAD_ERR_NO_FILE){if($photoUpload['error']!==UPLOAD_ERR_OK||$photoUpload['size']<1||$photoUpload['size']>5242880)throw new RuntimeException('Report photo must be up to 5 MB.');$photoMime=(new finfo(FILEINFO_MIME_TYPE))->file($photoUpload['tmp_name']);$photoType=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$photoMime]??null;if(!$photoType)throw new RuntimeException('Report photo must be JPG, PNG, or WebP.');$photoDir=__DIR__.'/uploads/event_reports';if(!is_dir($photoDir)&&!mkdir($photoDir,0700,true)&&!is_dir($photoDir))throw new RuntimeException('Could not prepare report photo storage.');$photoName=bin2hex(random_bytes(24)).'.'.$photoType;if(!move_uploaded_file($photoUpload['tmp_name'],$photoDir.'/'.$photoName))throw new RuntimeException('Could not save the report photo.');$reportPhotoPath='uploads/event_reports/'.$photoName;}
   if($updateID){$save=$pdo->prepare("UPDATE event_reports SET eventID=?,principalID=?,title=?,periodStart=?,periodEnd=?,objectives=?,outcomes=?,attendanceSummary=?,issues=?,recommendations=?,reportPhoto=?,reportPhotoDescription=?,status='Submitted',submittedAt=NOW(),reviewedAt=NULL WHERE reportID=? AND submittedBy=? AND status IN ('Resubmit','Needs Revision')");$save->execute([$eventID,$principalID,$title,$start,$end,$objectives,$outcomes,$auto,$issues?:null,$recommendations?:null,$reportPhotoPath,$reportPhotoDescription?:null,$updateID,$uid]);}else{$save=$pdo->prepare("INSERT INTO event_reports(eventID,submittedBy,principalID,title,periodStart,periodEnd,objectives,outcomes,attendanceSummary,issues,recommendations,reportPhoto,reportPhotoDescription,status,submittedAt) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'Submitted',NOW())");$save->execute([$eventID,$uid,$principalID,$title,$start,$end,$objectives,$outcomes,$auto,$issues?:null,$recommendations?:null,$reportPhotoPath,$reportPhotoDescription?:null]);}   $notice=$pdo->prepare('INSERT INTO notifications(userID,title,message,link) VALUES(?,?,?,?)');$notice->execute([$principalID,'New event report submitted',$user['name'].' submitted “'.$title.'” for '.$event['eventName'].'.','admin_reports.php']);$message='Report sent to the Principal.';
  }catch(RuntimeException $ex){$error=$ex->getMessage();}catch(Throwable $ex){$error='Could not send the report. Please check the database setup and try again.';}
 }
}
$eventQ=$pdo->prepare("SELECT DISTINCT e.eventID,e.eventName,e.eventDate,e.eventTime,e.location,e.status,e.capacity,e.fee,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=e.eventID) registrations,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=e.eventID AND r.status='Approved') approved,(SELECT COUNT(*) FROM registrations r WHERE r.eventID=e.eventID AND r.status='Pending Verification') pending,(SELECT COUNT(*) FROM attendance a JOIN registrations r ON r.eventID=a.eventID AND r.studentID=a.studentID WHERE r.eventID=e.eventID AND r.status='Approved' AND a.status='Present') present,(SELECT COUNT(*) FROM attendance a JOIN registrations r ON r.eventID=a.eventID AND r.studentID=a.studentID WHERE r.eventID=e.eventID AND r.status='Approved' AND a.status='Absent') absent,(SELECT COUNT(*) FROM financial_assistance fa JOIN students s ON s.userID=fa.userID JOIN registrations r ON r.studentID=s.studentID WHERE r.eventID=e.eventID AND fa.status='Approved') assistance,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.eventID=e.eventID AND p.status='Verified') paid,(SELECT COUNT(*) FROM feedback f WHERE f.eventID=e.eventID) feedback FROM events e LEFT JOIN event_tasks t ON t.eventID=e.eventID WHERE e.createdBy=? OR t.assignedTo=? ORDER BY e.eventDate DESC,e.eventTime DESC");$eventQ->execute([$uid,$uid]);$events=$eventQ->fetchAll();
$reports=[];if($schemaError===''){$reportsQ=$pdo->prepare('SELECT er.*,e.eventName,p.name AS principalName FROM event_reports er LEFT JOIN events e ON e.eventID=er.eventID LEFT JOIN users p ON p.userID=er.principalID WHERE er.submittedBy=? ORDER BY er.submittedAt DESC');$reportsQ->execute([$uid]);$reports=$reportsQ->fetchAll();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event reports | SchoolSphere</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/teacher.css?v=5"><link rel="stylesheet" href="assets/ui-polish.css?v=28"><link rel="stylesheet" href="assets/portal.css?v=12"><link rel="stylesheet" href="assets/school-sphere.css?v=18"></head><body class="teacher-dashboard"><div class="teacher-layout"><?php require __DIR__.'/teacher_nav.php';?><main class="teacher-main"><header class="teacher-topbar"><div><span class="teacher-eyebrow">EVENT PERFORMANCE</span><h1>Event reports</h1></div></header><div class="teacher-content"><section class="teacher-panel report-intro"><h2>Build a report for the Principal</h2><p>Attendance, registrations, assistance, payments and feedback totals are added from SEMS records. Add the event purpose, results, issues and recommendations before sending.</p></section><?php if($message):?><div class="portal-notice success"><?=school_h($message)?></div><?php endif;?><?php if($error):?><div class="portal-notice error"><?=school_h($error)?></div><?php endif;?>
<section class="teacher-panel"><div class="teacher-panel-heading"><h2>Event performance at a glance</h2><p>Only events you organise or have a committee task for.</p></div><div class="report-event-grid"><?php if(!$events):?><p>No events are assigned to you yet.</p><?php endif;?><?php foreach($events as $ev):?><article><span><?=school_h($ev['status'])?> · <?=school_h(date('d M Y',strtotime($ev['eventDate'])))?></span><h3><?=school_h($ev['eventName'])?></h3><p><?=school_h($ev['location'])?> · <?= (int)$ev['registrations']?> registrations · <?= (int)$ev['approved']?> approved</p><div><b><?= (int)$ev['present']?> / <?= (int)$ev['approved']?></b> present <b><?= (int)$ev['absent']?></b> absent <b><?= (int)$ev['assistance']?></b> approved assistance</div><small>Verified event payments RM <?=number_format((float)$ev['paid'],2)?> · <?= (int)$ev['feedback']?> feedback</small></article><?php endforeach;?></div></section>
<section class="teacher-panel"><div class="teacher-panel-heading"><h2>Write and send a report</h2><p>The Principal receives this report in Reports and gets an inbox notification.</p></div><form method="post" enctype="multipart/form-data" class="report-composer"><input type="hidden" name="csrf" value="<?=school_h($csrf)?>"><label>Report title<input name="title" maxlength="180" required placeholder="Example: Colour Run event report"></label><label>Event<select name="eventID" required><option value="">Choose an event</option><?php foreach($events as $ev):?><option value="<?= (int)$ev['eventID']?>"><?=school_h($ev['eventName'])?> · <?=school_h($ev['eventDate'])?></option><?php endforeach;?></select></label><label>Objectives and planned activities<textarea name="objectives" rows="4" maxlength="10000" required placeholder="What was the event intended to achieve? What activities were planned?"></textarea></label><label>Outcomes and achievements<textarea name="outcomes" rows="5" maxlength="10000" required placeholder="What happened? Summarise participation, delivery and results."></textarea></label><label>Optional event photo<input type="file" name="reportPhoto" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP · up to 5 MB</small></label><label>Photo description (optional)<input name="reportPhotoDescription" maxlength="1000"></label><label>Issues and follow-up needed<textarea name="issues" rows="4" maxlength="10000" placeholder="Any incidents, gaps, delays or unresolved matters?"></textarea></label><label>Recommendations for next time<textarea name="recommendations" rows="4" maxlength="10000" placeholder="What should be continued or improved?"></textarea></label><button class="teacher-primary-button" name="submit_event_report" value="1">Send report to Principal</button></form></section>
<section class="teacher-panel"><div class="teacher-panel-heading"><h2>Reports sent</h2><p>Principal review status and feedback.</p></div><div class="submitted-report-list"><?php if(!$reports):?><p>No reports sent yet.</p><?php endif;?><?php foreach($reports as $r):?><details class="submitted-report"><summary><span><strong><?=school_h($r['title'])?></strong><small><?=school_h($r['eventName']??'Event record unavailable')?> · <?=school_h($r['submittedAt'])?></small></span><b class="report-status <?=school_h(strtolower(str_replace(' ','-',$r['status'])))?>"><?=school_h($r['status'])?></b></summary><div class="report-print"><p><strong>Event date:</strong> <?=school_h($r['periodStart'])?></p><p><strong>Objectives:</strong><br><?=nl2br(school_h($r['objectives']))?></p><p><strong>Outcomes:</strong><br><?=nl2br(school_h($r['outcomes']))?></p><p><strong>System event metrics:</strong><br><?=nl2br(school_h($r['attendanceSummary']))?></p><p><strong>Issues:</strong><br><?=nl2br(school_h($r['issues']?:'None reported'))?></p><p><strong>Recommendations:</strong><br><?=nl2br(school_h($r['recommendations']?:'None provided'))?></p><?php if($r['principalRemarks']):?><p class="principal-response"><strong>Principal remarks:</strong><br><?=nl2br(school_h($r['principalRemarks']))?></p><?php endif;?><?php if(in_array($r['status'],['Resubmit','Needs Revision'],true)&&$r['eventID']):?><details class="report-revision"><summary>Edit and resend this report</summary><form method="post" enctype="multipart/form-data" class="report-composer"><input type="hidden" name="csrf" value="<?=school_h($csrf)?>"><input type="hidden" name="updateReportID" value="<?=(int)$r['reportID']?>"><label>Report title<input name="title" maxlength="180" required value="<?=school_h($r['title'])?>"></label><label>Event<select name="eventID" required><?php foreach($events as $ev):?><option value="<?=(int)$ev['eventID']?>" <?=(int)$r['eventID']===(int)$ev['eventID']?'selected':''?>><?=school_h($ev['eventName'])?></option><?php endforeach;?></select></label><label>Objectives<textarea name="objectives" rows="4" maxlength="10000" required><?=school_h($r['objectives'])?></textarea></label><label>Outcomes<textarea name="outcomes" rows="5" maxlength="10000" required><?=school_h($r['outcomes'])?></textarea></label><label>Optional event photo<input type="file" name="reportPhoto" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP · up to 5 MB</small></label><label>Photo description (optional)<input name="reportPhotoDescription" maxlength="1000" value="<?=school_h($r['reportPhotoDescription']??'')?>"></label><label>Issues<textarea name="issues" rows="4" maxlength="10000"><?=school_h($r['issues'])?></textarea></label><label>Recommendations<textarea name="recommendations" rows="4" maxlength="10000"><?=school_h($r['recommendations'])?></textarea></label><button class="small-button" name="submit_event_report" value="1">Update and resend</button></form></details><?php endif;?><small>Sent to <?=school_h($r['principalName']??'Principal')?> · <?=school_h($r['submittedAt'])?><?php if($r['reviewedAt']):?> · Reviewed <?=school_h($r['reviewedAt'])?><?php endif;?></small><button type="button" class="small-button" onclick="window.print()">Print report</button></div></details><?php endforeach;?></div></section></div></main></div></body></html>






















